from PIL import Image
img = Image.open('/app/output/final_poster.png')

# Scan a horizontal line through the title area for non-BG pixels
for y in [195, 210, 240, 270, 310, 350]:
    non_bg = 0
    for x in range(196, 2800, 5):
        px = img.getpixel((x, y))
        if px not in [(10,14,26), (17,22,40), (22,28,50)]:
            non_bg += 1
    print(f'y={y}: {non_bg} non-bg samples')

# Check hero card area
for y in range(480, 850, 10):
    non_bg = 0
    for x in range(160, 3348, 10):
        px = img.getpixel((x, y))
        if px not in [(10,14,26), (17,22,40), (22,28,50)]:
            non_bg += 1
    if non_bg > 0:
        print(f'y={y}: {non_bg} non-bg samples')
        break

# Check around timeline nodes
for x in [280, 707, 1134, 1561, 1988, 2415, 2842, 3269]:
    for dy in range(-3, 4):
        px = img.getpixel((x, 1200 + dy))
        if px not in [(10,14,26), (17,22,40), (22,28,50), (30,38,62)]:
            print(f'Node at x={x}: color={px}')" 2>&1

