from PIL import Image
img = Image.open('/app/output/final_poster.png')

# Check warning callout at Chrome 118 position (y ~860-1000, x ~1763-2213)
for y in range(850, 1020, 5):
    non_bg = 0
    for x in range(1760, 2220, 3):
        px = img.getpixel((x, y))
        if px not in [(10,14,26), (17,22,40), (22,28,50), (30,38,62), (46,36,10)]:
            non_bg += 1
    if non_bg > 5:
        pass  # content present

# Check amber warning pixels exist
amber_count = 0
for y in range(850, 1020):
    for x in range(1760, 2220):
        px = img.getpixel((x, y))
        if px == (251, 191, 36):
            amber_count += 1
            if amber_count <= 3:
                print(f'Amber pixel at ({x}, {y})')
print(f'Total amber pixels in warning area: {amber_count}')

# Check footer
for x in [200, 400, 600]:
    for y in [4800, 4830, 4850, 4880]:
        px = img.getpixel((x, y))
        if px not in [(10,14,26), (17,22,40)]:
            print(f'Footer content at ({x},{y}): {px}')
            break

# Bottom accent bar
for x in [100, 1754, 3400]:
    px = img.getpixel((x, 4962))
    print(f'Bottom bar at x={x}: {px}')

print('All checks passed.')
" 2>&1

